import{_ as t,c as h,o,a2 as a}from"./chunks/framework.B7el9cAC.js";const d=JSON.parse('{"title":"Câu Hỏi Thường Gặp (FAQ)","description":"","frontmatter":{},"headers":[],"relativePath":"appendix/faq.md","filePath":"appendix/faq.md","lastUpdated":1774640327000}'),i={name:"appendix/faq.md"};function g(r,n,c,l,e,s){return o(),h("div",null,[...n[0]||(n[0]=[a('<h1 id="cau-hoi-thuong-gap-faq" tabindex="-1">Câu Hỏi Thường Gặp (FAQ) <a class="header-anchor" href="#cau-hoi-thuong-gap-faq" aria-label="Permalink to &quot;Câu Hỏi Thường Gặp (FAQ)&quot;">​</a></h1><blockquote><p>Tổng hợp những câu hỏi học sinh hay thắc mắc khi ôn thi Tin học THPT</p></blockquote><hr><h2 id="🌐-chuong-2-–-mang-may-tinh" tabindex="-1">🌐 Chương 2 – Mạng Máy Tính <a class="header-anchor" href="#🌐-chuong-2-–-mang-may-tinh" aria-label="Permalink to &quot;🌐 Chương 2 – Mạng Máy Tính&quot;">​</a></h2><h3 id="❓-router-va-modem-khac-nhau-the-nao-nha-toi-dung-mot-hop-—-vay-la-cai-gi" tabindex="-1">❓ Router và Modem khác nhau thế nào? Nhà tôi dùng một hộp — vậy là cái gì? <a class="header-anchor" href="#❓-router-va-modem-khac-nhau-the-nao-nha-toi-dung-mot-hop-—-vay-la-cai-gi" aria-label="Permalink to &quot;❓ Router và Modem khác nhau thế nào? Nhà tôi dùng một hộp — vậy là cái gì?&quot;">​</a></h3><p><strong>Trả lời:</strong></p><ul><li><strong>Modem</strong> chuyển đổi tín hiệu từ nhà mạng (VNPT/Viettel/FPT) thành tín hiệu số.</li><li><strong>Router</strong> phân phối kết nối Internet cho các thiết bị trong nhà, cấp địa chỉ IP nội bộ.</li></ul><p>Hầu hết thiết bị gia đình hiện nay là <strong>modem-router tích hợp</strong> – hai chức năng trong một hộp. Trong bài thi, hãy phân biệt chúng theo <strong>chức năng</strong> chứ không phải hình dạng vật lý.</p><hr><h3 id="❓-đia-chi-mac-va-đia-chi-ip-–-cai-nao-quan-trong-hon" tabindex="-1">❓ Địa chỉ MAC và địa chỉ IP – cái nào quan trọng hơn? <a class="header-anchor" href="#❓-đia-chi-mac-va-đia-chi-ip-–-cai-nao-quan-trong-hon" aria-label="Permalink to &quot;❓ Địa chỉ MAC và địa chỉ IP – cái nào quan trọng hơn?&quot;">​</a></h3><p><strong>Trả lời:</strong> Cả hai đều quan trọng, nhưng dùng ở tầng khác nhau:</p><table tabindex="0"><thead><tr><th></th><th>MAC</th><th>IP</th></tr></thead><tbody><tr><td>Tầng</td><td>Tầng 2 (Data Link)</td><td>Tầng 3 (Network)</td></tr><tr><td>Phạm vi</td><td>Chỉ trong LAN</td><td>LAN và Internet</td></tr><tr><td>Ai dùng</td><td>Switch</td><td>Router</td></tr><tr><td>Thay đổi được không</td><td>Không (về lý thuyết)</td><td>Có (DHCP cấp tự động)</td></tr></tbody></table><p>Trong đề thi thường hỏi phân biệt hai loại địa chỉ này — nhớ: <strong>MAC = vật lý = Switch</strong>, <strong>IP = logic = Router</strong>.</p><hr><h3 id="❓-tcp-va-udp-—-khi-nao-dung-cai-nao" tabindex="-1">❓ TCP và UDP — khi nào dùng cái nào? <a class="header-anchor" href="#❓-tcp-va-udp-—-khi-nao-dung-cai-nao" aria-label="Permalink to &quot;❓ TCP và UDP — khi nào dùng cái nào?&quot;">​</a></h3><p><strong>Trả lời:</strong></p><ul><li><strong>TCP</strong> khi dữ liệu cần <strong>chính xác 100%</strong>: web (HTTP/HTTPS), email, tải file, chuyển khoản ngân hàng.</li><li><strong>UDP</strong> khi cần <strong>tốc độ thời gian thực</strong> và chấp nhận mất một vài gói: video call, game online, DNS.</li></ul><p>Mẹo nhớ: &quot;<strong>TCP = Tin Cậy Phải</strong>&quot; (phải đến đủ), &quot;<strong>UDP = Ưu tiên Độ nhanh</strong>&quot;.</p><hr><h3 id="❓-ip-192-168-1-1-la-cua-ai" tabindex="-1">❓ IP 192.168.1.1 là của ai? <a class="header-anchor" href="#❓-ip-192-168-1-1-la-cua-ai" aria-label="Permalink to &quot;❓ IP 192.168.1.1 là của ai?&quot;">​</a></h3><p><strong>Trả lời:</strong> Thường là <strong>địa chỉ IP của Router</strong> trong mạng gia đình (gateway mặc định). Máy tính của bạn thường có IP 192.168.1.x (x từ 2 đến 254). Cả hai đều là <strong>IP nội bộ (private IP)</strong> — không phải IP công cộng trên Internet.</p><hr><h2 id="🤖-chuong-3-–-tri-tue-nhan-tao" tabindex="-1">🤖 Chương 3 – Trí Tuệ Nhân Tạo <a class="header-anchor" href="#🤖-chuong-3-–-tri-tue-nhan-tao" aria-label="Permalink to &quot;🤖 Chương 3 – Trí Tuệ Nhân Tạo&quot;">​</a></h2><h3 id="❓-ai-thong-minh-đen-muc-nao-co-the-thay-the-con-nguoi-khong" tabindex="-1">❓ AI &quot;thông minh&quot; đến mức nào? Có thể thay thế con người không? <a class="header-anchor" href="#❓-ai-thong-minh-đen-muc-nao-co-the-thay-the-con-nguoi-khong" aria-label="Permalink to &quot;❓ AI &quot;thông minh&quot; đến mức nào? Có thể thay thế con người không?&quot;">​</a></h3><p><strong>Trả lời:</strong> AI hiện tại đều là <strong>AI yếu (Narrow AI)</strong> — rất giỏi trong <strong>một lĩnh vực hẹp</strong> (chơi cờ, nhận diện ảnh, dịch thuật...) nhưng không thể làm mọi việc như con người. <strong>AI mạnh (General AI)</strong> — loại có thể suy nghĩ tổng quát như người — chưa tồn tại trong thực tế.</p><p>Trong ngắn và trung hạn: AI sẽ <strong>thay thế các công việc lặp đi lặp lại</strong>, nhưng những việc cần <strong>sáng tạo thật sự, cảm xúc, và đạo đức</strong> vẫn cần con người.</p><hr><h3 id="❓-hallucination-cua-ai-la-gi-vi-du-thuc-te" tabindex="-1">❓ Hallucination của AI là gì? Ví dụ thực tế? <a class="header-anchor" href="#❓-hallucination-cua-ai-la-gi-vi-du-thuc-te" aria-label="Permalink to &quot;❓ Hallucination của AI là gì? Ví dụ thực tế?&quot;">​</a></h3><p><strong>Trả lời:</strong> AI &quot;ảo giác&quot; khi nó <strong>bịa ra thông tin không có thật</strong> nhưng trình bày rất tự tin. Ví dụ:</p><ul><li>ChatGPT bịa ra tên sách, tên tác giả, năm xuất bản không tồn tại</li><li>AI trả lời sai số liệu thống kê nhưng nghe rất đáng tin</li></ul><p><strong>Nguyên nhân:</strong> AI hoạt động bằng cách dự đoán từ tiếp theo có xác suất cao nhất — không phải tra cứu sự thật. Khi thiếu dữ liệu, nó tiếp tục &quot;đoán&quot; thay vì nói &quot;Tôi không biết&quot;.</p><hr><h3 id="❓-nlp-la-gi-co-phai-chi-la-dich-thuat-khong" tabindex="-1">❓ NLP là gì? Có phải chỉ là dịch thuật không? <a class="header-anchor" href="#❓-nlp-la-gi-co-phai-chi-la-dich-thuat-khong" aria-label="Permalink to &quot;❓ NLP là gì? Có phải chỉ là dịch thuật không?&quot;">​</a></h3><p><strong>Trả lời:</strong> <strong>Không</strong> — NLP (Natural Language Processing) rộng hơn nhiều:</p><ul><li><strong>Dịch máy</strong> (Google Dịch)</li><li><strong>Phân tích cảm xúc</strong> (nhận ra review tích cực/tiêu cực)</li><li><strong>Chatbot</strong> (hiểu câu hỏi của người dùng)</li><li><strong>Tóm tắt văn bản</strong></li><li><strong>Nhận dạng giọng nói</strong> (Siri, Google Assistant)</li><li><strong>Lọc thư rác</strong> (phân loại email)</li></ul><p>Dịch thuật chỉ là một ứng dụng nhỏ trong NLP.</p><hr><h2 id="🗄️-chuong-4-–-co-so-du-lieu-sql" tabindex="-1">🗄️ Chương 4 – Cơ Sở Dữ Liệu &amp; SQL <a class="header-anchor" href="#🗄️-chuong-4-–-co-so-du-lieu-sql" aria-label="Permalink to &quot;🗄️ Chương 4 – Cơ Sở Dữ Liệu &amp; SQL&quot;">​</a></h2><h3 id="❓-csdl-va-dbms-khac-nhau-the-nao" tabindex="-1">❓ CSDL và DBMS khác nhau thế nào? <a class="header-anchor" href="#❓-csdl-va-dbms-khac-nhau-the-nao" aria-label="Permalink to &quot;❓ CSDL và DBMS khác nhau thế nào?&quot;">​</a></h3><p><strong>Trả lời:</strong></p><ul><li><strong>CSDL (Database)</strong> = kho dữ liệu (ví dụ: toàn bộ thông tin học sinh trường THPT X)</li><li><strong>DBMS</strong> = phần mềm quản lý kho đó (ví dụ: MySQL, PostgreSQL)</li></ul><p>Ví dụ: MySQL là <strong>DBMS</strong> (phần mềm), còn database <code>school_db</code> bên trong MySQL mới là <strong>CSDL</strong>.</p><hr><h3 id="❓-khi-nao-dung-khoa-chinh-phuc-composite-primary-key" tabindex="-1">❓ Khi nào dùng khóa chính phức (composite primary key)? <a class="header-anchor" href="#❓-khi-nao-dung-khoa-chinh-phuc-composite-primary-key" aria-label="Permalink to &quot;❓ Khi nào dùng khóa chính phức (composite primary key)?&quot;">​</a></h3><p><strong>Trả lời:</strong> Dùng khi <strong>không có cột đơn nào đủ để định danh duy nhất</strong> mỗi hàng.</p><p>Ví dụ điển hình: Bảng <code>DiemThi(MaHS, MaMon, Diem)</code> — một học sinh thi nhiều môn nên <code>MaHS</code> bị trùng; một môn có nhiều học sinh thi nên <code>MaMon</code> bị trùng. Chỉ <strong>kết hợp (MaHS + MaMon)</strong> mới tạo ra định danh duy nhất.</p><hr><h3 id="❓-lenh-sql-select-co-van-đe-gi-khong" tabindex="-1">❓ Lệnh SQL SELECT * có vấn đề gì không? <a class="header-anchor" href="#❓-lenh-sql-select-co-van-đe-gi-khong" aria-label="Permalink to &quot;❓ Lệnh SQL SELECT * có vấn đề gì không?&quot;">​</a></h3><p><strong>Trả lời:</strong> Về mặt chức năng thì đúng — trả về tất cả cột. Nhưng trong thực tế:</p><ul><li>Tốn băng thông hơn (lấy cả cột không cần)</li><li>Khó đọc và bảo trì code</li><li>Nguy cơ lộ dữ liệu nhạy cảm</li></ul><p><strong>Trong bài thi:</strong> <code>SELECT *</code> vẫn được chấp nhận. Trong thực tế lập trình chuyên nghiệp, nên chỉ định tên cột cụ thể.</p><hr><h3 id="❓-inner-join-va-join-khac-nhau-khong" tabindex="-1">❓ INNER JOIN và JOIN khác nhau không? <a class="header-anchor" href="#❓-inner-join-va-join-khac-nhau-khong" aria-label="Permalink to &quot;❓ INNER JOIN và JOIN khác nhau không?&quot;">​</a></h3><p><strong>Trả lời:</strong> <code>JOIN</code> và <code>INNER JOIN</code> là <strong>giống nhau</strong> — <code>INNER</code> là mặc định khi không ghi gì. Cả hai chỉ trả về hàng <strong>có dữ liệu khớp ở cả hai bảng</strong>.</p><p>Các loại JOIN khác:</p><ul><li><code>LEFT JOIN</code> — trả về tất cả hàng bảng trái, kể cả khi không có khớp bên phải</li><li><code>RIGHT JOIN</code> — ngược lại</li><li>Trong chương trình THPT, chỉ cần biết <code>INNER JOIN</code></li></ul><hr><h2 id="🌍-chuong-5-–-html-css" tabindex="-1">🌍 Chương 5 – HTML &amp; CSS <a class="header-anchor" href="#🌍-chuong-5-–-html-css" aria-label="Permalink to &quot;🌍 Chương 5 – HTML &amp; CSS&quot;">​</a></h2><h3 id="❓-html-co-phai-ngon-ngu-lap-trinh-khong" tabindex="-1">❓ HTML có phải ngôn ngữ lập trình không? <a class="header-anchor" href="#❓-html-co-phai-ngon-ngu-lap-trinh-khong" aria-label="Permalink to &quot;❓ HTML có phải ngôn ngữ lập trình không?&quot;">​</a></h3><p><strong>Trả lời:</strong> <strong>Không.</strong> HTML là <strong>ngôn ngữ đánh dấu (markup language)</strong> — nó mô tả cấu trúc và nội dung, không có biến, vòng lặp, hay hàm. Ngôn ngữ lập trình thực sự cho web là <strong>JavaScript</strong>.</p><p>Bộ ba web frontend: <strong>HTML</strong> (cấu trúc) + <strong>CSS</strong> (trình bày) + <strong>JavaScript</strong> (hành vi).</p><hr><h3 id="❓-ul-vs-ol-—-khi-nao-dung-cai-nao" tabindex="-1">❓ <code>&lt;ul&gt;</code> vs <code>&lt;ol&gt;</code> — khi nào dùng cái nào? <a class="header-anchor" href="#❓-ul-vs-ol-—-khi-nao-dung-cai-nao" aria-label="Permalink to &quot;❓ `&lt;ul&gt;` vs `&lt;ol&gt;` — khi nào dùng cái nào?&quot;">​</a></h3><p><strong>Trả lời:</strong></p><ul><li><strong><code>&lt;ul&gt;</code> (Unordered List):</strong> Dùng khi <strong>thứ tự không quan trọng</strong> — danh sách sở thích, nguyên liệu, tính năng sản phẩm.</li><li><strong><code>&lt;ol&gt;</code> (Ordered List):</strong> Dùng khi <strong>thứ tự quan trọng</strong> — hướng dẫn từng bước, các bước công thức nấu ăn, quy trình.</li></ul><p>Mẹo nhớ: &quot;ordered&quot; = có trật tự = đánh số 1, 2, 3.</p><hr><h3 id="❓-colspan-va-rowspan-trong-bang-html-la-gi" tabindex="-1">❓ <code>colspan</code> và <code>rowspan</code> trong bảng HTML là gì? <a class="header-anchor" href="#❓-colspan-va-rowspan-trong-bang-html-la-gi" aria-label="Permalink to &quot;❓ `colspan` và `rowspan` trong bảng HTML là gì?&quot;">​</a></h3><p><strong>Trả lời:</strong></p><ul><li><strong><code>colspan=&quot;n&quot;</code></strong> — một ô chiếm <strong>n cột</strong> theo chiều ngang.</li><li><strong><code>rowspan=&quot;n&quot;</code></strong> — một ô chiếm <strong>n hàng</strong> theo chiều dọc.</li></ul><p>Ví dụ: <code>&lt;td colspan=&quot;3&quot;&gt;</code> trong bảng 3 cột = ô đó chiếm toàn bộ chiều ngang hàng đó.</p><hr><h3 id="❓-nen-nhung-css-theo-cach-nao" tabindex="-1">❓ Nên nhúng CSS theo cách nào? <a class="header-anchor" href="#❓-nen-nhung-css-theo-cach-nao" aria-label="Permalink to &quot;❓ Nên nhúng CSS theo cách nào?&quot;">​</a></h3><p><strong>Trả lời:</strong></p><table tabindex="0"><thead><tr><th>Cách</th><th>Khi nào dùng</th></tr></thead><tbody><tr><td><strong>Inline</strong> <code>style=&quot;...&quot;</code></td><td>Chỉnh 1 phần tử nhanh, không khuyến khích dùng nhiều</td></tr><tr><td><strong>Internal</strong> <code>&lt;style&gt;</code> trong <code>&lt;head&gt;</code></td><td>Trang đơn lẻ, bài tập nhỏ</td></tr><tr><td><strong>External</strong> file <code>.css</code> riêng</td><td>Dự án nhiều trang — <strong>cách chuyên nghiệp</strong></td></tr></tbody></table><p>Trong bài thi thực hành, Internal hoặc Inline đều được chấp nhận.</p><hr><h2 id="⚖️-chuong-6-–-đao-đuc-nghe-it" tabindex="-1">⚖️ Chương 6 – Đạo Đức &amp; Nghề IT <a class="header-anchor" href="#⚖️-chuong-6-–-đao-đuc-nghe-it" aria-label="Permalink to &quot;⚖️ Chương 6 – Đạo Đức &amp; Nghề IT&quot;">​</a></h2><h3 id="❓-an-danh-tren-mang-co-the-lam-gi-cung-đuoc-khong" tabindex="-1">❓ Ẩn danh trên mạng có thể làm gì cũng được không? <a class="header-anchor" href="#❓-an-danh-tren-mang-co-the-lam-gi-cung-đuoc-khong" aria-label="Permalink to &quot;❓ Ẩn danh trên mạng có thể làm gì cũng được không?&quot;">​</a></h3><p><strong>Trả lời:</strong> <strong>Không.</strong> Dù bạn dùng tên giả, mỗi thiết bị kết nối Internet đều có <strong>địa chỉ IP</strong> được nhà mạng ghi lại. Cơ quan chức năng có thể yêu cầu các nền tảng (Facebook, Google) và nhà mạng cung cấp thông tin người dùng theo pháp luật.</p><p><strong>Luật An ninh mạng Việt Nam 2018</strong> quy định rõ trách nhiệm pháp lý với hành vi vi phạm trên mạng, kể cả khi dùng tài khoản ảo.</p><hr><h3 id="❓-cyberbullying-co-the-bi-xu-ly-phap-ly-khong" tabindex="-1">❓ Cyberbullying có thể bị xử lý pháp lý không? <a class="header-anchor" href="#❓-cyberbullying-co-the-bi-xu-ly-phap-ly-khong" aria-label="Permalink to &quot;❓ Cyberbullying có thể bị xử lý pháp lý không?&quot;">​</a></h3><p><strong>Trả lời:</strong> <strong>Có.</strong> Tùy theo mức độ:</p><ul><li><strong>Phạt hành chính:</strong> Theo Nghị định 15/2020/NĐ-CP (sửa đổi bởi Nghị định 14/2022), vi phạm về thông tin sai sự thật, xúc phạm uy tín người khác có thể bị phạt đến 30 triệu đồng.</li><li><strong>Truy cứu hình sự:</strong> Nếu gây hậu quả nghiêm trọng (đe dọa tính mạng, xúc phạm danh dự nghiêm trọng) có thể bị truy cứu theo Bộ Luật Hình sự.</li></ul><hr><h3 id="❓-mat-khau-nhu-the-nao-la-đu-manh" tabindex="-1">❓ Mật khẩu như thế nào là đủ mạnh? <a class="header-anchor" href="#❓-mat-khau-nhu-the-nao-la-đu-manh" aria-label="Permalink to &quot;❓ Mật khẩu như thế nào là đủ mạnh?&quot;">​</a></h3><p><strong>Trả lời:</strong> Mật khẩu mạnh cần:</p><ul><li>✅ <strong>Ít nhất 12 ký tự</strong> (càng dài càng tốt)</li><li>✅ Kết hợp <strong>chữ HOA + chữ thường + số + ký tự đặc biệt</strong> (!@#$%)</li><li>✅ <strong>Không có nghĩa</strong> — tránh tên, ngày sinh, từ trong từ điển</li><li>✅ <strong>Khác nhau</strong> cho mỗi tài khoản</li><li>❌ Tránh: <code>123456</code>, <code>password</code>, <code>qwerty</code>, tên + năm sinh</li></ul><p>Cách nhớ mật khẩu phức tạp: Dùng <strong>passphrase</strong> — lấy chữ đầu của một câu bạn thuộc lòng: <em>&quot;Tôi học lớp 12 trường THPT Nguyễn Huệ&quot;</em> → <code>ThL12tTHPTNH@2024</code></p><hr><h3 id="❓-hacker-mu-trang-lam-gi-co-hop-phap-khong" tabindex="-1">❓ Hacker mũ trắng làm gì? Có hợp pháp không? <a class="header-anchor" href="#❓-hacker-mu-trang-lam-gi-co-hop-phap-khong" aria-label="Permalink to &quot;❓ Hacker mũ trắng làm gì? Có hợp pháp không?&quot;">​</a></h3><p><strong>Trả lời:</strong> <strong>Hacker mũ trắng (White Hat / Ethical Hacker)</strong> là chuyên gia bảo mật được <strong>thuê hợp pháp</strong> để:</p><ul><li>Tìm lỗ hổng bảo mật trong hệ thống</li><li>Báo cáo lại để được vá (không khai thác)</li><li>Tham gia chương trình Bug Bounty (nhận tiền thưởng cho lỗ hổng tìm được)</li></ul><p>Đây là nghề nghiệp hợp pháp và được trả lương rất cao. Khác hoàn toàn với <strong>hacker mũ đen (Black Hat)</strong> tấn công trái phép để trục lợi.</p><hr><h2 id="📝-cau-hoi-ve-thi-cu" tabindex="-1">📝 Câu Hỏi Về Thi Cử <a class="header-anchor" href="#📝-cau-hoi-ve-thi-cu" aria-label="Permalink to &quot;📝 Câu Hỏi Về Thi Cử&quot;">​</a></h2><h3 id="❓-mon-tin-hoc-thi-theo-hinh-thuc-nao" tabindex="-1">❓ Môn Tin học thi theo hình thức nào? <a class="header-anchor" href="#❓-mon-tin-hoc-thi-theo-hinh-thuc-nao" aria-label="Permalink to &quot;❓ Môn Tin học thi theo hình thức nào?&quot;">​</a></h3><p><strong>Trả lời:</strong> Kỳ thi tốt nghiệp THPT môn Tin học thi theo hình thức <strong>trắc nghiệm</strong> (40 câu trong 50 phút). Đề thi bao gồm kiến thức lý thuyết từ chương trình Tin học lớp 10, 11, 12 — tập trung vào các chương trong tài liệu này.</p><hr><h3 id="❓-nen-hoc-thuoc-long-hay-hieu-ban-chat" tabindex="-1">❓ Nên học thuộc lòng hay hiểu bản chất? <a class="header-anchor" href="#❓-nen-hoc-thuoc-long-hay-hieu-ban-chat" aria-label="Permalink to &quot;❓ Nên học thuộc lòng hay hiểu bản chất?&quot;">​</a></h3><p><strong>Trả lời:</strong> <strong>Kết hợp cả hai, nhưng ưu tiên hiểu bản chất.</strong> Lý do:</p><ul><li>Đề thi trắc nghiệm thường có câu hỏi vận dụng (không thể chỉ thuộc lòng định nghĩa)</li><li>Hiểu bản chất giúp suy luận ra đáp án ngay cả khi quên từ ngữ chính xác</li><li>Một số khái niệm như SQL, HTML cần <strong>nhớ cú pháp chính xác</strong> — nên học thuộc</li></ul><p><strong>Thứ tự ưu tiên:</strong> Hiểu bản chất → Ghi nhớ điểm mấu chốt → Nhớ cú pháp kỹ thuật</p><hr><h3 id="❓-nhung-loi-nao-hay-bi-tru-điem-nhat" tabindex="-1">❓ Những lỗi nào hay bị trừ điểm nhất? <a class="header-anchor" href="#❓-nhung-loi-nao-hay-bi-tru-điem-nhat" aria-label="Permalink to &quot;❓ Những lỗi nào hay bị trừ điểm nhất?&quot;">​</a></h3><p><strong>Trả lời:</strong> Theo thống kê từ các đề thi trước, học sinh hay mất điểm vì:</p><ol><li><strong>Nhầm Switch với Hub</strong> — Switch chuyển đúng cổng, Hub phát tán tất cả</li><li><strong>Nhầm CSDL với DBMS</strong> — MySQL là DBMS (phần mềm), không phải CSDL</li><li><strong>Nghĩ MAC address có thể định tuyến qua Internet</strong> — MAC chỉ dùng trong LAN</li><li><strong>Nhầm <code>&lt;ul&gt;</code> và <code>&lt;ol&gt;</code></strong> — ordered = có số thứ tự</li><li><strong>Nghĩ AI đồng cảm thật sự</strong> — AI chỉ bắt chước ngôn ngữ cảm xúc</li><li><strong>Nhầm White Hat và Black Hat hacker</strong></li><li><strong>Quên <code>PRIMARY KEY</code> phải Unique + Not Null cả hai điều kiện</strong></li></ol>',108)])])}const p=t(i,[["render",g]]);export{d as __pageData,p as default};
